Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('262','2103009','Servicio de apoyo financiero para subsidiar el consumo de combustibles líquidos derivados del petróleo','Recursos destinados a disminuir el costo al usuario final de los combustibles líquidos derivados del petróleo teniendo como referente los precios internacionales.','110');
