Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('268','2103024','Servicio de educación informal en temas de hidrocarburos','Jornadas, capacitaciones, talleres, foros y otro tipo de eventos con funcionarios, ciudadanía y partes interesadas para que adquieran conocimientos y  contribuir con la apropiación en temáticas específicas acerca del subsector hidrocarburos. Incluye el desarrollo de sesiones de formación y capacitación, así como la presentación de resultados de investigación en las acciones que se realizan.','110');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('269','2103008','Servicio de monitoreo a los controles implementados en el transporte de combustibles','Comprende las acciones que se realizan para la verificación de la legalidad del combustible transportado.','110');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('270','2103010','Servicio de asistencia técnica para la reconversión socio laboral de las actividades de contrabando de combustibles','Consiste en la implementación de programas que permitan realizar actividades económicas viables para los pobladores de zonas en las cuales se genera el contrabando de combustibles.','110');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('271','2103027','Servicios de apoyo para el desarrollo de proyectos de inversión social en territorios estratégicos para el sector de hidrocarburos','Corresponde a la entrega de recursos en especie o monetarios para la identificación, formulación y ejecución de proyectos de inversión social en territorios estratégicos para el sector hidrocarburos.','110');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('272','2103026','Documentos de planeación','Documentos cuyo objetivo es plasmar una visión de futuro a nivel país, entidad territorial, comunidad, sector, región, entidad o cualquier nivel de desagregación que se requiera. Incluye objetivos, estrategias, metas e indicadores.','110');
