Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('274','2103012','Servicio de divulgación para la promoción y posicionamiento de los recursos hidrocarburíferos','Mediante los cuales se realiza promoción del potencial de hidrocarburos del país para incrementar la inversión en el sector.','110');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('275','2103003','Oleoductos construidos','Construcción de infraestructura utilizada para el transporte de petróleo.','110');
