Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('278','2103002','Oleoductos con mantenimiento','Mantenimiento de infraestructura utilizada para el transporte de petróleo.','110');
