Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('281','2103001','Casetas para estaciones de monitoreo de la actividad sísmica y volcánica','Infraestructura en la cual se desarrollan las actividades sísmicas para la exploración de los hidrocarburos. Contiene los equipos necesarios para sísmica como los geófonos y equipos de cómputo para el procesamiento de datos.','110');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('282','2103007','Refinerías construidas','Construcción de infraestructura utilizada para la transformación de hidrocarburos.','110');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('283','2103004','Poliductos con mantenimiento','Mantenimiento de infraestructura utilizada para el transporte de derivados del petróleo.','110');
