Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1058','2408018','Documentos de planeación','Documentos cuyo objetivo es plasmar una visión de futuro a nivel país, entidad territorial, comunidad, sector, región, entidad o cualquier nivel de desagregación que se requiera. Incluye objetivos, estrategias, metas e indicadores','130');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1059','2408023','Servicio de Información Geográfica - SIG','Corresponde al levantamiento del inventario de la red vial urbana dispuesta para el servicio de transporte público organizado, con el fin de conocer las condiciones de operabilidad y funcionalidad de una vía, a partir de una descripción detallada de sus condiciones físicas, geométricas, de diseño y estado superficial del pavimento, así como de obras complementarias y servicios anexos. ','130');
