Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('654','2302065','Servicio de Educación informal sobre las Tecnologías de la Información y las Comunicaciones con enfoque diferencial','Indica los Servicio de educación con enfoque diferencial sobre las TIC tanto virtuales como presenciales. Cursos de en promedio 3 horas, para todo tipo de población, teniendo en cuenta el enfoque diferencial. ','121');
