Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('861','2403112','Sedes de instituciones de educación superior o terciaria mejoradas','Incluye intervencionesde tipo estructural tales como: reparaciones, remodelaciones, ampliaciones o mantenimientos estéticos de infraestructura educativa  del Centro de Estudios Aeronáuticos de conformidad con los lineamientos técnicos del sector.','125');
