Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('864','2403118','Dependencias aeronáuticas construidas','Incluye la infraestructura en la que se encuentran ubicados los sistemas de comunicación, navegación y vigilancia del sistema de navegación aérea.','125');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('865','2403111','Sedes de instituciones de educación superior fortalecidas','Incluye la adquisición y entrega de  dotación básica (pupitres, tableros, lockers,entre otros) de conformidad con los lineamientos técnicos del sector educación. ','125');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('866','2403084','Estudios de preinversión','Incluye la realización de los estudios requeridos en las fases de pre factibilidad, factibilidad o definitivos .','125');
