Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('868','2403110','Servicios de gestión del riesgo físico en estudiantes y docentes','Incluye aquellos servicios que se presten a la comunidad educativa del Centro de Estudios Aeronáuticos para ampararlos y/o prevenir alguna situación de riesgo contra su integridad.','125');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('869','2403104','Servicio de apoyo financiero para el desarrollo de servicios de aviación de las entidades territoriales','Contempla la cofinanciación de iniciativas formuladas por las entidades territoriales para la ejecución de obras de infraestructura, previo al proceso de viabilización técnica, jurídica, financiera y de sostenibilidad, realizado por la Unidad Administrativa Especial de la Aeronáutica Civil.','125');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('870','2403108','Servicio de información para la gestión educativa ofrecida por el  Centro de Estudios Aeronáuticos implementado','Corresponde al proceso que asegura la disposición de la información de manera accesible, confiable y oportuna.','125');
