Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('872','2403117','Servicio de educación informal en navegación aérea y servicios  aeroportuarios','Incluye todo tipo de estrategias encaminadas a fortalecer la apropiación social de conocimientos por parte de la comunidad aeronáutica y potenciales usuarios o proveedores de bienes y  servicios.','125');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('873','2403106','Servicios de atención psicosocial a estudiantes y docentes','Incluye aquellos servicios que preste el Centro de Estudios Aeronáuticos a la comunidad educativa de la educación superior o terciaria para superar o prevenir daños e impactos psicológicos o emocionales.','125');
