Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3941','1707001','Documentos de lineamientos técnicos','Documentos cuyo objetivo es describir y explicar instrumentos, estándares, requisitos y condiciones necesarias para llevar a cabo un proceso o actividad','97');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3942','1707070','Documentos de política','Documentos cuyo objetivo es emitir los lineamientos de política para el Ministerio de Agricultura y Desarrollo Rural, las entidades adscritas y vinculadas, gremios, asociaciones o comités de productores y secretarías de agricultura, entidades del orden departamental, municipal y distrital.','97');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3943','1707069','Servicio de divulgación y socialización','Comprende el desarrollo  de la divulgación y socialización de política, documentos de lineamientos técnicos, documentos  de seguimiento y evaluación.','97');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3944','1707068','Documentos de evaluación','Documentos que contienen los resultados del proceso de seguimiento, evaluación y análisis realizado. ','97');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3945','1707067','Documentos metodológicos','Documentos cuyo objetivo es describir y explicar métodos, herramientas analíticas o procesos  de seguimiento y evaluación.','97');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3946','1707065','Servicio de registro de la actividad pesquera y acuícola','En atención a la dinámica de la pesca y la acuicultura, se generan registros permanentes de los usuarios autorizados para desarrollar cualquier tipo de actividad relacionada con el sector; dichos registros son sujeto de constante actualización. ','97');
