Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3949','1707021','Servicio de certificación de semillas para siembra','Controla la producción de semillas certificadas y seleccionadas y supervisa los procesos de importación, unidades de investigación de semillas producidas por métodos de mejoramiento convencionales y no convencionales, como los Organismos Modificados Genéticamente.','97');
