Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3957','1707043','Servicios de control de parásitos para especies de interés agropecuario','Consiste en el desarrollo de prácticas enfocadas a promover y proteger la salud de las especies animales por medio del control de parásitos internos y/o extermos . Incluye aplicación de vermífugos, baños, entre otros','97');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3958','1708041','Servicio de extensión agropecuaria','Comprende acciones de acompañamiento integral orientadas a diagnosticar, recomendar, actualizar, formar, transferir, asistir, empoderar y generar capacidad en los productores agropecuarios para que estos incorporen en su actividad productiva prácticas, productos tecnológicos, tecnologías, conocimientos y comportamientos que beneficien su desempeño y mejoren su competitividad y sostenibilidad.','98');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3959','1708039','Servicio de conservación y mantenimiento de especies animales, vegetales y microbiales en bancos de germoplasma','Corresponde al manejo, preservación y utilización adecuados de los Recursos Genéticos conocidos, de tal forma que estos rindan un beneficio sostenible para las generaciones presentes y futuras','98');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3960','1708038','Servicio de asistencia técnica agropecuaria','Atención integral a productores agrícolas, pecuarios, forestales y acuícolas o pesqueros en: Aptitud de suelos; Tecnologías y recursos para actividad productiva; Procedimientos para acceder al financiamiento; Mercadeo; organización de productores y Dotación de infraestructura productiva.','98');
