Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4022','1709092','Infraestructura de trapiche panelero con mantenimiento','Hace referencia al mantenimiento de la infraestructura de trapiche panelero. Un trapiche panelero es aquel establecimiento donde se extrae y evapora el jugo de la caña de azúcar y se elabora la panela con un rendimiento o capacidad igual a 100 kg/h.  (Resolución 779 de 2006).','99');
