Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4180','1901131','Servicio de promoción de vida saludable y condiciones no transmisibles','Desarrollo de acciones de bienestar y disfrute de vida sana, promoción de condiciones y estilos de vida saludables, donde crecen personas, familias y comunidades, trabajan y envejecen, prevención y control de las condiciones crónicas no transmisibles','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4181','1901033','Servicio de investigación, desarrollo e innovación tecnológica en epidemiologia','El servicio de investigación, desarrollo e innovación tecnológica en epidemiología  incluye generación boletines o alertas,  tablas de vigilancia de salud pública, reglamento Sanitario Internacional de redes especiales como laboratorios de salud pública, bancos de sangre y trasplantes de la Dirección de Redes en Salud Pública, Dirección de Prestación de Servicios y Atención Primaria entre otros.','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4182','1901032','Servicio de educación formal del talento humano en cáncer','El servicio de educación formal del talento humano en cáncer es mediante el cual se da a los programas con registro calificado en cáncer  .','102');
