Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4195','1901062','Servicio de articulación de los integrantes del Sistema Nacional de Gestión del Riesgo de desastres con los diferentes actores del sector salud','Incluye el servicio de Articulación real y efectiva de los integrantes del Sistema Nacional de Gestión del Riesgo de desastres con los diferentes actores del Sector Salud.','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4196','1901004','Documentos normativos','Incluye documentos normativos a nivel de ley, decretos, resoluciones y  circulares  de Promoción y prevención,  de emergencias y desastres,  de calidad,  en Promoción social, de epidemiología y demografía, de prestación de Servicio y atención primaria, de medicamentos y tecnologías en salud, en medicamentos de control especial monopolio del estado, en talento  humano en salud, en regulación general de tecnologías en salud, normas expedidas sobre  sangre y componentes anatómicos,  normas expedidas sobre  dispositivos médicos y equipos biomédicos.','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4197','1901129','Servicio de promoción de los derechos sexuales y reproductivos y la equidad de género','Recursos que buscan promover acciones y generar condiciones, capacidades y medios para que los individuos, familias y sociedad gocen del nivel mas alto de salud sexual y reproductiva, ejerciendo los derechos sexuales y los derechos reproductivos','102');
