Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4200','1901029','Servicio de investigación, desarrollo e innovación tecnológica en cáncer','Servicio de investigación, desarrollo e innovación tecnológica en cáncer  permite realizar las investigaciones científicas, proyectos de investigación, Prototipos diseñados, desarrollos tecnológicos,  propiedad intelectual, Patentes, publicaciones  indexadas nacionales e internacionales y divulgación en eventos científicos en  cáncer entre otras.','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4201','1901044','Servicio de evaluación externa del desempeño para bancos de sangre y Servicio de transfusión','El Servicio permite realizar la evaluación externa del desempeño para bancos de sangre y Servicio de transfusión','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4202','1901023','Servicio de emisión de conceptos técnicos de viabilidad para laboratorios de salud pública','El servicio de Emisión de conceptos técnicos de viabilidad para Laboratorios de Salud Pública incluye Conceptos técnicos de viabilidad para proyectos de sedes (adecuación, ampliación, reforzamiento, construcción, modificación, reestructuración) para los  Laboratorios de Salud Pública.','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4203','1901005','Documentos metodológicos','Incluye los documentos de protocolo de atención integral en salud con enfoque psicosocial a población  indígena, ROM, negra, discapacitada, Jefes cabeza de hogar, desplazados,  infantil niñez y  la tercera edad  víctimas del conflicto armado de los departamentos y municipios entre otros','102');
