Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4206','1901074','Servicio de conformación de Comité de Urgencias','El servicio de conformación del Comité de Urgencias permite a las entidades contar con una organización que permita tomar decisiones en caso de emergencias, lo debe formalizar las entidades territoriales.','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4207','1901067','Servicio de asistencia técnica de sensibilización de la necesidad de prestación de servicios a quien porte el emblema.','Comprende el servicio de asistencia técnica en a las Entidades territoriales, Secretarias departamentales, distritales y locales de salud y las Instituciones Prestadoras de Servicios de salud con emblema y sensibilización real y efectiva de la necesidad de prestación de servicios a quien porte el emblema.','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4208','1901066','Servicio de asistencia técnica de los compromisos con las Entidades Administradoras de Planes de Beneficios, las administradoras de Riesgos Laborales , en el marco de sus competencias.','Incluye el servicio de asistencia técnica con las entidades administradoras de Planes de Beneficios Empresas Administradoras de Planes de Beneficio, las Administradoras de riesgos Laborales articulados en el Plan Territorial de salud en el marco de sus competencias','102');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('4209','1901057','Servicio de apoyo financiero y vigilancia de los tribunales seccionales','Incluye el servicio de apoyo financiero y vigilancia de los Tribunales seccionales de ética médica y odontológica financiados y vigilados en la utilización de recursos.','102');
