Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3477','1304010','Servicio de autorizaciones a entidades financierassupervisadas y partes interesadas','Decidir mediante acto administrativo, sobre una solicitud de una entidad supervisada, o de particulares (personas naturales o jurídicas), respecto a algún trámite que por el marco legal, requiera la autorización previa y expresa de la Superintendencia Financiera de Colombia. ','81');
