Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3480','1304017','Servicio de funciones Jurisdiccionales para entidades vigiladas y consumidores financieros','Dirimir, con carácter definitivo y con las facultades propias de un juez, las controversias que surjan entre los consumidores financieros y las entidades vigiladas relacionadas exclusivamente con la ejecución y el cumplimiento de las obligaciones contractuales que asuman con ocasión de la actividad financiera, bursátil, aseguradora y cualquier otra relacionada con el manejo, aprovechamiento o inversión de los recursos captados del público.','81');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3481','1304031','Servicio de Información al Sistema Nacional Anti Lavado de Activos y Contra la Financiación del Terrorismo implementación','Corresponde al proceso que asegura la disposición de la información que permitan entender los perfiles de las organizaciones al margen de la ley, en el análisis y persecución de las finanzas ilícitas generadas por las actividades delictivas del lavado de activos, e impedir la filtración de estos dineros en la economía del país','81');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3482','1304027','Servicio de información implementado','Corresponde al proceso que asegura la disposición de la información de manera accesible, confiable y oportuna','81');
