Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3487','1304016','Servicio de estadística del sector financiero','Suministrar información sobre las diferentes cifras e indicadores financieros y económicos del mercado, con el fin de facilitar la toma de decisiones de nuestros clientes internos y externos.','81');
