Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3516','1305019','Servicio de control fisico en el ingreso de mercancia de contrabando por pasos fronterizos ilegales','Acciones orientadas a la realización de operativos de control físico como capacidad preventiva  y reactiva en zona de frontera que minimice el ingreso de mercancía de contrabando.','82');
