Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3540','1399056','Documentos normativos','Incluye la realización de documentos de contenido normativo para la reglamentación de los proyectos de ley presentados y aprobados.','83');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3541','1399055','Documentos metodológicos','Documentos cuyo objetivo es describir y explicar métodos, herramientas analíticas, o procesos que determinan un camino o forma de realizar un análisis en particular.','83');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3542','1501034','Servicios tecnológicos ','Corresponde al proceso que asegura la disponibilidad del servicio a través de la infraestructura informática tanto de software como de hardware, y lo relacionado con seguridad informática','84');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3543','1501033','Servicio de apoyo logístico para el aprovisionamiento del personal y carga','Acciones orientadas a la cobertura de los servicios de policía en el territorio nacional por medio de la adquisición de aeronaves de ala fija para el transporte de personas y de carga ','84');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3544','1501019','Comandos de policía construidos y dotados','Corresponde a un inmueble resultado de obras de edificación en terrenos no construidos o cuya área esté libre por autorización de demolición total, de acuerdo a las áreas priorizadas por la Policía Nacional de acuerdo con las necesidades focalizadas en materia de convivencia y seguridad ciudadana . Incluye la dotación.','84');
