Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3657','1504034','Servicio de Información para el seguimiento de asuntos internacionales implementado','Corresponde al proceso que asegura la disposición de la información sobre el cumplimiento de los convenios internacionales maritimos suscritos por Colombia mediante leyes nacionales de manera accesible, confiable y oportuna','86');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3658','1504033','Documentos de política','Incluye la realización de documentos de política orientados al desarrollo marìtimo, fluvial y costero ','86');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3659','1504035','Servicio de asistencia técnica en asuntos marítimos internacionales','Acciones orientadas a la asistencia técnica de la autoridad marítima colombiana en escenarios estratégicos internacionales, tales como OMI, IALA, OHI, entre otros, donde se toman decisiones en temas cruciales para Dimar y para Colombia en asuntos tales como seguridad de la navegación, la protección del medio marino y la protección de buques e instalaciones portuarias. La participación en estos escenarios incluye la elaboración y aporte de documentos técnicos, conceptos, posiciones institucionales y nacionales, que son insumo para la elaboración de normatividad y linemientos internacionales que propenden por el correcto uso y aprovechamiento de los mares.','86');
