Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3662','1504021','Servicio de señalización marítima y fluvial','Comprende la instalación de ayudas a la navegación por medio de la señalización marítima y fluvial (Boyas, faros, balizas, enfilaciones, racons y otros - AIS- Sistema de Identificación Automática) para brindar información oportuna sobre: los peligros en las proximidades a la costa, y señalizar los canales navegables de puertos públicos. De igual forma, lo anterior permite una navegación expedita y segura a las embarcaciones  en la jurisdicción marítima colombiana, de acuerdo a los estándares internacionales.','86');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3663','1504030','Servicio de seguimiento de ruta ','Implementación de sistemas de localización, y monitoreo a embarcaciones que realicen navegación en altura, con el fin de ser identificadas de acuerdo con la normatividad vigente. ','86');
