Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3690','1505022','Infraestructura hospitalaria de nivel 1 adecuada y dotada ','Corresponde a un inmueble sobre el cual se adelantan obras de edificación que cambian, de manera completa o parcial, el uso del inmueble, garantizando la permanencia total o parcial del inmueble original para la prestación de los servicios de salud. Incluye la dotación ','87');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3691','1505011','Servicios Deportivos','Busca facilitar y estimular la práctica metódica del ejercicio físico, cuya finalidad es superar una meta o vencer a un adversario en competencia sujeta a reglas. Incluye la gestión y ejecución de actividades orientadas a la dotación equipos deportivos, patrocinio de torneos, otorgamiento de descuentos para la adquisición de implementos deportivos e ingreso a gimnasios y escuelas deportivas.','87');
