Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3696','1505007','Servicios de Atención a la Familia',' Servicios de asesoría y asistencia psicosocial y jurídica para la atención de problemáticas individuales, familiares y conyugales y a la promoción de soluciones orientadas al fortalecimiento de la red familiar del personal militar y civil activo de las FFMM.','87');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3697','1505002','Servicio de apoyo financiero para la educación formal de la Policía Nacional','Orientado a dar alcance a los servicios de educación formal para los policías','87');
