Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1153','2501016','Servicio de información implementado','Servicios orientados al diseño, desarrollo, implantación, mantenimiento y adecuación de sistemas de información y herramientas tecnológicas  que contribuyan al ejercicio del control y vigilancia fiscal','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1154','2501004','Servicio de control fiscal participativo','Servicio dirigido a fortalecer la participación de la ciudadanía en las actividades de control fiscal','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1155','2501017','Servicio de seguimiento de políticas publicas','Corresponde al seguimiento de políticas para el cumplimiento de la función de control y vigilancia de la gestión fiscal y el resarcimiento al daño del patrimonio público','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1156','2501002','Documentos normativos',null,'134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1157','2501001','Documentos de lineamientos técnicos','Documentos cuyo objetivo es describir y explicar instrumentos, estándares, requisitos y condiciones necesarias para llevar a cabo un proceso o actividad','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1158','2501013','Servicio de control fiscal macro','Este servicio se refiere al uso, articulación e incorporación de los análisis macro generados en el sector en los informes de auditoría.','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1159','2501012','Servicio de control fiscal micro','Este servicio hace referencia a la vigilancia y control a  las entidades u organismos que administran recursos o bienes públicos.','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1160','2501006','Servicio de divulgación para fortalecer la imagen de control fiscal','Servicio dirigido a fortalecer la comunicación de resultados de la Contraloría para posicionar a la Entidad ante la opinión pública.','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1161','2501019','Documentos de investigación','Documentos técnicos cuyo objetivo es describir los resultados de las investigaciones académicas en control fiscal. ','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1162','2501018','Servicio de educación informal en áreas relacionadas con el control fiscal','Desarrollo de actividades de capacitación  orientadas al conocimiento en áreas relacionadas al control fiscal.','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1163','2501009','Servicio de investigación en el proceso de responsabilidad fiscal','Servicio establecido para determinar y establecer la responsabilidad de los servidores públicos y de los particulares, cuando en el ejercicio de la gestión fiscal o con ocasión de ésta, causen por acción u omisión y en forma dolosa o culposa, un daño al patrimonio del Estado','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1164','2501010','Servicio de jurisdicción coactiva','La jurisdicción coactiva se define como la facultad de cobrar directamente, sin que medie intervención judicial, las deudas a  favor del Estado, adquiriendo la doble calidad de juez y parte','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1165','2501015','Servicio de información actualizado','Servicios orientados al diseño, desarrollo, implantación, mantenimiento y adecuación de sistemas de información y herramientas tecnológicas  que contribuyan al ejercicio del control y vigilancia fiscal','134');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1166','2502002','Servicio de asistencia técnica para atención, orientación y asesoría en materia de Derechos Humanos, el Derecho Internacional Humanitario y en escenarios de paz','Desarrollo de las acciones orientadas a la atención y  tramite de peticiones presentadas por los ciudadanos, en materia de Derechos Humanos, DerechoInternacional Humanitario y en el proceso de construcción de la paz','135');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1167','2502005','Documentos de lineamientos técnicos','Documentos cuyo objetivo es describir y explicar instrumentos, estándares, requisitos y condiciones necesarias para llevar a cabo un proceso o actividad','135');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1168','2502003','Servicio de educación informal en materia de Derechos Humanos y Derecho Internacional Humanitario','Desarrollo de actividades educativas orientadas al conocimiento y  ejercicio de los DDHH y el DIH','135');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1169','2502001','Servicio de advertencia y seguimiento a los riesgos de vulneración de los Derechos Humanos, el Derecho Internacional Humanitario y en los escenarios de paz','Es la observación permanente de la dinámica de la confrontación armada y el análisis de los indicios y hechos para detectar e identificar situaciones que amenacen  los derechos humanos y el derecho internacional humanitario de la población civil, o los procesos de construcción de la paz','135');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1170','2502004','Servicio de divulgación de los derechos humanos y del derecho internacional humanitario de la población','Diseño, desarrollo y elaboración de materiales para la promoción y divulgación de los DDHH y el DIH, incluye entre otros: folletos, afiches, pancartas, material grafico, audiovisual, rompecabezas, cartillas, libros, etc.','135');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1171','2502008','Documentos normativos',null,'135');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1172','2502009','Documentos metodológicos','Documentos cuyo objetivo es describir y explicar métodos, herramientas analíticas o procesos que determinan un camino o forma de realizar un análisis en particular. Específicamente contienen el protocolo de investigación, gestión documental y archivística en materia de violaciones de Derechos Humanos e Infracciones al Derecho Internacional Humanitario ocurridas con ocasión del conflicto armado interno colombiano.','135');
