Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2137','3706011','Servicio de consulta bibliográfica','Incluye la dotación del centro de documentación con actualizaciones, suscripciones a revistas especializadas, entre otros materiales de consulta adquiridos para el acceso del público.','173');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2138','3706001','Servicio de educación informal en derechos de autor a autores y no autores','Capacitaciones en derechos de autor para aquellos que son autores y quienes están en prospecto de serlo.','173');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2139','3706010','Servicios tecnológicos','Corresponde al proceso que asegura la disponibilidad del servicio a través de la infraestructura informática tanto de software como de hardware, y lo relacionado con seguridad informática.','173');
