Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2734','4399016','Sedes mantenidas','Incluye mantenimiento preventivo y correctivo de edificios y zonas comunes,  trabajos de carpintería metálica y en maderareparaciones menores, trabajos de vidrios, trabajos de mampostería, trabajos de ornamentación, trabajos hidráulicos y sanitarios, servicios de jardinería, cortinería y cerrajería, pintura y reparación de muebles y pintura de espacios físicos.','194');
