Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2829','0202002','Servicio de asistencia técnica para la construcción, adecuación y ampliación de infraestructuras para la atención integral a la primera infancia.','Seguimiento, verificación técnica, gerencia integral y/o asistencia técnica para construcción de centros de atención para niños y niñas en los municipios.','35');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2830','0203002','Documentos de Lineamientos Técnicos','Documentos que orienten las acciones administrativas y políticas para el cumplimiento de una temática en específico','36');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2831','0203004','Documentos de investigación','Documento de análisis conceptual o empírico que contribuya al mejoramiento y comprensión de las condiciones institucionales, avances y retos  de la política pública anticorrupción.','36');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2832','0203008','Servicio de asistencia técnica en cultura de la integridad y transparencia','Generación de transformaciones individuales y colectivas mediante el desarrollo e implementación de herramientas pedagógicas innovadoras y lineamientos metodológicos y técnicos para una cultura de Integridad.','36');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2833','0203007','Servicio de asistencia técnica para el ejercicio del control social, rendición de cuentas y participación ciudadana','Fortalecimiento de la participación ciudadana, control social, rendición y petición de cuentas mediante implementación de estrategias que incentiven las capacidades institucionales y de la ciudadanía en estos temas.','36');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2834','0203005','Servicios de asistencia técnica en Ley de Transparencia y del Derecho de Acceso a la Información Pública Nacional','Fortalecimiento del proceso de implementación de la Ley de Transparencia y del Derecho de Acceso a la Información Pública Nacional a través de asistencia técnica a los diferentes sujetos obligados de la Ley.','36');
