Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2837','0203003','Documentos Metodológicos','Documentos que contribuyan a entender, comprender, visibilizar y facilitar la implementación de normas o políticas públicas, a través de la descripción de objetivos, conceptos, pasos y requerimientos.','36');
