Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2861','0206008','Servicios de apoyo para la consolidación de la Acción Integral contra Minas Antipersonal','Enfocado a Promover, desarrollar y fortalecer espacios que permitan coordinar y articular entidades del orden internacional, nacional y territorial para la planificación, implementación y seguimiento de intervenciones de la Acción Integral Contra Minas Antipersonal.','39');
