Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2865','0206002','Servicios de educación informal en ERM (Educación en el Riesgo de Minas)','Implementación de procesos pedagógicos sobre promoción de comportamientos seguros  y prevención de los riesgos,  dirigidos a la comunidad con sospecha o afectada por Minas Antipersonal, a través de Difusión de información pública, Educación y capacitación o Gestión del riesgo comunitario. ','39');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2866','0206004','Documentos de Planeación','Implementación de procesos para la coordinación y articulación Nación  -Territorio de la AICMA, dirigido a autoridades del nivel departamental y/o local. Eventualmente, se brinda a actores AICMA (del orden nacional y/o cooperación) y a comunidades afectadas y/o con sospecha de Minas Antipersonal.','39');
