Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2907','0209009','Servicio de habilitación del suelo','Servicio prestado para habilitar el suelo con el fin de ser usado para construcción de proyectos de infraestructura','42');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2908','0210010','Servicio de apoyo financiero para acciones y actividades relacionadas con el logro y mantenimiento de la paz.','Financiación para cualquier acción y actividad relacionado con el logro y mantenimiento de Paz.','43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2909','0210011','Servicio de apoyo financiero a programas y proyectos para el logro y mantenimiento de la paz',null,'43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2910','0210013','Servicio de apoyo para el acceso a activos productivos y de comercialización para proyectos de ciclo corto e ingreso rápido','Apoyo en activos productivos que se pueden clasificar en capital humano, la tierra y los bienes de capital productivo (Infraestructura, maquinaria y equipos, insumos y material vegetal, especies zootécnicas y acuícolas). Comercialización comprende actividades relacionadas con el proceso que va desde el acopio de los productos agropecuarios y distribución.','43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2911','0210001','Servicio de divulgación de la cultura de paz y resolución no violenta de conflictos',null,'43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2912','0210019','Servicios de apoyo financiero para la implementación de esquemas alternativos de conservación y pagos por servicios ambientales (PSA)','Financiamiento de proyectos que tienen como objetivo la conservación de áreas, mediante acuerdos voluntarios, entre propietarios de predios e interesados en el mantenimiento de los servicios ambientales que prestan esas áreas.  El esquema de conservación utilizado puede ser el del Pago por Servicios Ambientales (PSA) definido en la regulación aplicable y otros esquemas alternativos de conservación.','43');
