Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2918','0210021','Servicios de apoyo financiero para la generación de capacidades en evaluación y formulación de proyectos','Financiamiento de evaluación, formulación y priorización de perfiles de proyectos asociativos, recibidos mediante convocatorias abiertas, cuyos beneficiarios son actores locales, organizaciones de pequeños y medianos productores y de base comunitaria que establece la Ley, los gremios, las comunidades indígenas, las comunidades afrocolombianas, las organizaciones campesinas y de colonos y las organizaciones de mujeres que se encuentran en municipios PDET y territorios afectados por el conflicto.','43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2919','0210017','Servicio de apoyo para la implementación del Plan de Atención Inmediata','Corresponde al apoyo para el cumplimiento de las obligaciones reciprocas, que surgen del acuerdo de voluntades suscrito entre el Gobierno Nacional y las familias inscritas al programa, en  desarrollo del Plan de Atención Inmediata para la Transición económica.','43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2920','0210015','Servicio de apoyo financiero para la transición de los hogares vinculados a cultivos ilícitos',null,'43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2921','0210018','Servicios de apoyo financiero para proyectos de restauración de ecosistemas degradados en áreas protegidas y Áreas de Especial Importancia Ambiental (AEIA) ','Financiamiento de proyectos de restauración ecológica en ecosistemas que han sido transformados y degradados por la deforestación, causada, entre otras cosas, por el establecimiento de cultivos ilícitos, el uso inadecuado del suelo en actividades agroindustriales, la producción agropecuaria y la minería a cielo abierto.','43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2922','0210005','Vía terciaria construida',null,'43');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2923','0210012','Servicio de apoyo para las unidades productivas para el autoconsumo de los hogares en situación de vulnerabilidad social','Corresponde a la entrega de recursos en especie para generación de huertas, cría de animales y pesca artesanal para el autoconsumo de hogares vinculados al Programa Nacional Integral de Sustitución de cultivos.','43');
