Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2994','0303007','Servicio de información relacionado con la prestación de los servicios públicos domiciliarios','Corresponde al servicio prestado a través del Sistema Único de Información, en el cual se registra información relacionada con la prestación de los servicios públicos domiciliarios','48');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2995','0303004','Servicio de vigilancia a la correcta prestación de los servicios públicos domiciliarios',null,'48');
