Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2997','0303016','Servicio de asistencia técnica para la formalización de prestadores de servicios públicos domiciliarios','Corresponde al servicio de acompañamiento para que los prestadores de servicios públicos queden inscritos en el Registro Único de Prestadores de Servicios Públicos - RUPS, el cual permite asegurar la formalización de dichos prestadores','48');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2998','0303018','Servicio de generación e implementación de agendas de trabajo participativo con la comunidad en el tema de servicios públicos domiciliarios','Corresponde al fortalecimiento de la participación ciudadana y control social mediante la implementación de estrategias para que los ciudadanos conozcan sus derechos, deberes y mecanismos de acceso para ejercerlos alrededor del tema de los servicios públicos.','48');
