Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3014','0399012','Sedes modificadas','Corresponde a un inmueble sobre el cual se realizan obras para variar su diseño arquitectónico o estructural, sin incrementar su área construida. (Corresponde a la licencia de construcción por modificación)','50');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3015','0399009','Sedes construidas','Corresponde a un inmueble resultado de obras de edificación en terrenos no construidos o cuya área esté libre por autorización de demolición total. No incluye la dotación del inmueble. (Corresponde a la licencia de construcción por obra nueva)','50');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3016','0399065','Documento para la planeación estratégica en TI','Documento cuyo objetivo es definir el marco de referencia que alinea la gestión de tecnologías  de la información con las políticas de estado y sectoriales que se definan sobre la materia.','50');
