Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3045','0401051','Servicio de geo información Estadística','Incluye la generación de estadísticas georreferenciadas para identificar patrones espaciales, valorar y predecir tendencias de la situación de un territorio con las variables demográficas, sociales y económicas a diferentes escalas de representación.','51');
