Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3145','0402017','Documentos de Investigación','Incluye las investigaciones que se realicen sobre el territorio colombiano desde la perspectiva geográfica en sus diversos aspectos: biofísico, ambiental, económico, social, cultural, turístico y de la organización espacial. ','52');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3114','0401081','Boletines Técnicos de la Cuenta Satélite Economía del Cuidado','Incluye el suministro de la representación cuantificada de la economía de un país o región  y la información desagregada complementaria, en un período de tiempo determinado a través del cálculo de la Cuenta Satélite de Economía del Cuidado.','51');
