Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3247','0505003','Documentos de planeación','Documentos cuyo objetivo es plasmar una visión de futuro a nivel país, entidad territorial, comunidad, sector, región, entidad o cualquier nivel de desagregación que se requiera. Incluye objetivos, estrategias, metas e indicadores','61');
