Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('3270','1101005','Servicio educativos para la promoción de Colombia en el exterior','Corresponde a las acciones desarrolladas en el marco del Plan de Promoción de Colombia en el Exterior, entre las cuales se encuentran conciertos, obras de teatro, presentaciones de danza, exposiciones, ciclos de cine y actividades académicas y culturales que muestran la riqueza cultural y artística de Colombia y diversifican su imagen ante la comunidad internacional','63');
