Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2166','3707087','Servicio de educación informal','Son  acciones que se realizan para contribuir al  conocimiento y apropiación de una temática específica.','174');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2167','3707086','Obras para el control y reducción de la erosión','Incluye la realización de obras para el control de erosión, como el tratamiento de regulación de la escorrentía superficial, los tratamientos de regulación de flujo hídrico en cauces, el incremento de infiltraciones, los tratamientos lineales, y la reforestación. ','174');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2168','3708900','Estaciones de Bomberos construidas y con dotación de mobiliario en los municipios','Producto Regalías','175');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2169','3708009','Estaciones de bomberos construidas','Hace referencia a la construcción y dotación de estaciones de bomberos (Clase 1, 2, 3 o 4). Las Estaciones de bomberos son las infraestructuras que protegen los bienes materiales y recursos técnicos para la atención de emergencias; como lo son los vehículos y el equipamiento (Resolución 661 de 2014).','175');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2170','3708014','Servicio de asistencia técnica y administrativa de los cuerpos de bomberos del país','Incluye el apoyo a los cuerpos de bomberos en la implementación de políticas y reglamentos de orden técnico, administrativo y operativo, así como la formulación de estrategias, planes y demás herramientas para los cuerpos de bomberos del país en: prevención y atención de incendios, preparativos y atención de rescates en todas sus modalidades, así como atención de incidenes con materiales peligrosos.','175');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2171','3708012','Servicio de certificación a Cuerpos de Bomberos de Colombia',' La Dirección Nacional de Bomberos de Colombia ejerce la inspección, vigilancia y control sobre los Cuerpos de Bomberos de Colombia conforme a lo establecido en el art. 24 de la ley 1575 de 2012. De acuerdo a lo anterior, mediante el certificado de cumplimiento expedido por la Dirección Nacional de Bomberos se acredita que un cuerpo de bomberos está capacitado para la prestación del servicio público esencial de bomberos.','175');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2172','3708013','Servicio de fortalecimiento a Cuerpos de Bomberos de Colombia','Incluye la dotación a los diferentes Cuerpos de Bomberos de Colombia con vehículos, equipos de protección personal y equipos, herramientas y accesorios para la atención de emergencias, así como el aseguramiento del personal misional.','175');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2173','3708004','Servicio de educación informal teórico-practico en atención de emergencias bomberilres.','Incluye la capacitación inferior a 160 horas y entrenamiento de las unidades bomberiles de los Cuerpos de Bomberos de Colombia. ','175');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2174','3708015','Estaciones de bomberos adecuadas','Incluye las intervenciones necesarias para adecuar un inmueble como estación de bomberos clase 1, 2, 3 o 4. ','175');
