Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2468','4102002','Servicio de atención tradicional a la primera infancia','Servicio dispuestos para atender a los niños y niñas en primera infancia, en los Hogares Comunitarios que brindan  cuidado, nutrición y protección.','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2469','4102037','Servicio de protección para el restablecimiento de derechos de niños, niñas, adolescentes y jóvenes','Servicios determinados por las autoridades administrativas dirigidos a garantizar y restablecer el ejercicio de los derechos de los niños, niñas, adolescentes y jóvenes, cuando sus derechos han sido amenazados  y/o vulnerados.','187');
