Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2472','4102038','Servicio dirigidos a la atención de niños, niñas, adolescentes y jóvenes, con enfoque pedagógico y restaurativo encaminados a la inclusión social','Servicio dirigidos a la atención de niños, niñas, adolescentes y jóvenes, con enfoque pedagógico y restaurativo encaminados a la inclusión social.','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2473','4102041','Servicio de asistencia técnica en el ciclo de políticas públicas de familia y otras relacionadas','Comprende la capacitación, asesoría y acompañamiento en el diseño e implementación de programas dirigidos a las familias y a la garantía de sus derechos y los de sus integrantes .','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2474','4102025','Documentos de investigación','Investigaciones, evaluaciones, análisis y estudios relacionados con el impacto o resultados de programas, efectos de intervenciones o situaciones sobre los niños, niñas y adolescentes y otros documentos que generen conocimiento para mejorar las atenciones dirigidas a esta población.','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2475','4102022','Servicio de divulgación para la promoción y prevención de los derechos de los niños, niñas y adolescentes','Estrategias mediante las cuales se difunde, motiva y sensibiliza a la sociedad en general acerca de la información de promoción y prevención de los derechos de los niños, niñas y adolescentes y se dan a conocer los mecanismos para su restablecimiento.  Incluye las acciones que se realizan para el intercambio de experiencias, con los agentes del Sistema Nacional de Bienestar Familiar','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2476','4102033','Centros de Atención Especializada - CAE para el restablecimiento de derechos con reforzamiento estructural','Reforzamiento estructural de centros que brindan atención a los adolescentes vinculados al Sistema de Responsabilidad Penal para Adolescentes brindándoles atención con Servicio de salud, educación, deporte, cultura, recreación y la restauración de los vínculos familiares.','187');
