Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2478','4102032','Centros de Atención Especializada - CAE para el restablecimiento de derechos restaurados','Restauración de centros que brindan atención a los adolescentes vinculados al Sistema de Responsabilidad Penal para Adolescentes brindándoles atención con Servicio de salud, educación, deporte, cultura, recreación y la restauración de los vínculos familiares.','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2479','4102016','Servicio de atención y prevención a la desnutrición desde el sector inclusión social','Servicio dirigidos a atender y prevenir la desnutrición en las mujeres gestantes,  mujeres en periodo de lactancia, los niños  y niñas, bajo estrategias que incluyen la atención nutricional, médica y psicosocial. ','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2480','4102005','Edificaciones de atención a la primera infancia adecuadas','Adecuación de infraestructuras dirigidas  específicamente  a prestar Servicio de atención integral a la primera infancia.  ','187');
