Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2482','4102042','Servicio de asistencia técnica a comunidades en temas de fortalecimiento del tejido social y construcción de escenarios comunitarios protectores de derechos','Incluye el desarrollo de acciones de intervención comunitaria,  transmisión de saberes intergeneracionales y acciones de formación comunitaria con enfoque diferencial, que favorezcan la activación de redes sociales e institucionales de protección de derechos de los integrantes de las familias.','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2483','4102019','Servicio para proceso de adopción de niños, niñas y adolescentes en situación de adoptabilidad en firme, por consentimiento o por autorización','Garantizan el ejercicio y restablecimiento de derechos de niños, niñas o adolescentes bajo procesos de atención provisional en medio diferente al de su familia biológica o extensa. Previenen mayores niveles de amenaza, inobservancia y vulneración, restablecen sus derechos según necesidades particulares y atendiendo factores de generatividad y vulnerabilidad de familia o redes sociales próximas.','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2484','4102036','Servicio de información con modelos de gestión tecnológica para el Sistema Nacional de Bienestar Familiar','Mediante los cuales operan los sistemas de información que se requieren para el cumplimiento de las funciones misionales del Sistema Nacional de Bienestar Familiar. Incluye total o parcialmente actividades de: Diseño; Desarrollo;  Implantación (mesas de ayuda y asistencia técnica para la operación); Mantenimiento; y Adecuación de la plataforma tecnológica.','187');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2485','4102015','Servicio de distribución de alimentos líquidos de alto valor nutricional','Mecanismos necesarios para el transporte, almacenamiento, distribución  y entrega de los alimentos líquidos de alto valor nutricional.','187');
