Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1543','3206011','Servicios de información para el seguimiento a los compromisos en cambio climático de Colombia','Incluye el monitoreo de los indicadores y variables climáticas, gases efecto invernadero, y vulnerabilidad, ex ante y . ','151');
