Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1556','3207013','Diques construidos','Muro grueso construido para contener la fuerza del agua, embalsarla o reducirla ','152');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1557','3207006','Servicio de restauración ecológica de ecosistemas marino costeros','Acciones orientadas a restablecer los ecosistemas de manglares degradados a una condición similar al ecosistema pre disturbio respecto a su composición, estructura y funcionamiento. Además el ecosistema resultante debe ser un sistema auto sostenible y debe garantizar la conservación de especies, del ecosistema en general así como de la mayoría de sus bienes y Servicio.','152');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1558','3207009','Servicio de control de especies invasoras y exóticas','Acciones orientadas a controlar las especies exóticas de carácter invasor que han sido capaces de colonizar efectivamente un área en donde se ha interrumpido la barrera geográfica y se han propagado sin asistencia humana directa en hábitats naturales o seminaturales y cuyo establecimiento y expansión amenaza los ecosistemas, hábitats o especies con daños económicos o ambientales. ','152');
