Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1941','3601005','Servicio de información de normatividad del Sistema General de Pensiones','El servicio de información provee a los ciudadanos de manera consolidada las normas relacionadas que regulan el Sistema General de Pensiones.','162');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1942','3601004','Servicio de gestión de la información de Historias Laborales','Sistema de consolidación de las historias laborales (cotización a pensiones) de los diferentes regímenes y fondos.','162');
