Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2227','3904022','Servicios de apoyo financiero para la Gestión del Conocimiento en Cultura y Apropiación Social de la Ciencia, la Tecnología y la Innovación','Busca financiar o cofinanciar acciones para el seguimiento, evaluación y mejora en el marco de procesos de Apropiación Social de la Ciencia','180');
