Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1637','3301123','Servicio de clasificación de producciones cinematográficas','Para dar cumplimiento al artículo 22 de la Ley 11 85 de 2008 que ordena que ninguna película podrá pasarse en salas de cine o sitios abiertos al público sin autorización previa de este comité con el fin de garantizar la protección de la primera infancia, la infancia y la adolescencia para garantizar.','155');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1638','3301088','Centros culturales construidos','Son todas aquellas infraestructuras culturales que se construyan en un predio o terreno donde no existen elementos o construcciones previstas. ','155');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1639','3301083','Museos construidos y dotados','Son todas aquellas infraestructuras culturales que se construyan en un predio o terreno donde no existen elementos o construcciones previstas. ','155');
