Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1667','3301124','Servicio de promoción de Colombia como escenario de rodaje de películas','En el marco del cumplimiento de la ley 1556, el Ministerio de Cultura y la Dirección de Cinematografía participan en eventos y actividades a nivel mundial con el fin de promocionar e incentivar el uso de los apoyos brindados por esta ley. ','155');
