Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1991','3603018','Servicios de orientación ocupacional','Proceso dinámico, flexible y continuo para la definición del perfil ocupacional y del perfil emprendedor, para direccionarlo a la oferta institucional.','164');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1992','3603004','Servicio de formación profesional integral','Constituye un proceso educativo teórico-práctico de carácter integral, orientado al desarrollo de conocimientos técnicos, tecnológicos y de actitudes y valores para la convivencia social, que le permiten a la persona actuar crítica y creativamente en el mundo del trabajo y de la vida.','164');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1993','3603017','Servicios de identificación y formulación de planes de Emprendimiento','Identificar ideas productivas y formular planes de negocio  pertinentes con el nuevo entorno territorial','164');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1994','3603001','Servicio de educación informal en educación solidaria','Indica el número de trabajadores que se forman en las empresas a través de programas de formación complementaria','164');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1995','3603011','Servicio de aseguramiento de calidad de la formación para el trabajo','Corresponde a las acciones realizadas para asegurar la calidad de la formación para el trabajo que se han prestado.','164');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2286','4001006','Documentos de lineamientos técnicos','Documentos cuyo objetivo es describir y explicar instrumentos, estándares, requisitos y condiciones necesarias para llevar a cabo un proceso o actividad','182');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2287','4001004','Documentos de planeación','Documentos cuyo objetivo es plasmar una visión de futuro a nivel país, entidad territorial, comunidad, sector, región, entidad o cualquier nivel de desagregación que se requiera. Incluye objetivos, estrategias, metas e indicadores','182');
