Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1706','3301068','Servicio de mantenimiento de infraestructura cultural','Ajuste o adaptación de una Infraestructura Cultural en la cual ya se estén desarrollando prácticas culturales, se busca garantizar la permanencia del inmueble original con las especificaciones requeridas. Este proceso puede o no tener reforzamiento estructural.','155');
