Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1708','3302066','Servicios de educación informal para la promoción y divulgación de la diversidad lingüística y sus medios de expresión y difusión','Contempla los servicios de educación continua ofertados en las áreas de lingüística, literatura, filología, semiótica a través de todos los medios de expresión y de difusión. Incluye los eventos como conferencias, conmemoraciones, conversatorios, encuentros, simposios y demás eventos de carácter académico que permiten el fortalecimiento de la gestión universitaria y la consolidación de la comunidad docente e investigativa del Instituto.','156');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1709','3302015','Servicio de educación para el trabajo a miembros de apoyo y comunidad académica','Talleres de actualización sobre el estado etnográfico, arqueológico y del patrimonio cultural de la nación. Talleres de actualización sobre el estado etnográfico, arqueológico y del patrimonio cultural de la nación.','156');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1710','3302067','Servicios de educación formal de posgrado','Servicio orientado a la formación de talento humano especializado  para contribuir a fortalecer las bases de la capacidad nacional para la generación, transferencia, apropiación y aplicación del conocimiento','156');
