Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2337','4003025','Servicios de apoyo financiero para la ejecución de proyectos de acueductos y alcantarillado',null,'184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2338','4003009','Servicio de Acueducto','Es la distribución de agua apta para el consumo humano, incluida su conexión y medición. También forman parte de éste servicio las actividades complementarias tales como captación de agua, procesamiento, tratamiento, almacenamiento, conducción y transporte.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2339','4003019','Alcantarillados ampliados','Conjunto de acciones y obras requeridas para aumentar la capacidad del alcantarillado en una misma área de cobertura.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2340','4003015','Acueductos construidos','Conjunto de acciones y obras para la implementación de sistemas de acueducto nuevos.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2341','4003040','Servicio de apoyo financiero en tratamiento de aguas residuales','Los sistemas de tratamiento de aguas residuales son el conjunto de operaciones requeridas para reducir la carga contaminante vertida a los cuerpos de agua, para mejorar la calidad del recurso hídrico y el bienestar de la población. Con la financiación de proyectos de descontaminación de aguas, se pretende reducir los impactos ambientales negativos generados en las cuencas hidrográficas del país.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2342','4003018','Alcantarillados construidos','Conjunto de acciones y obras para la implementación de sistemas de alcantarillado nuevos.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2343','4003047','Servicio de apoyo financiero para subsidios al consumo en los servicios públicos domiciliarios','Los subsidios al consumo están destinados a satisfacer necesidades básicas de los usuarios de los estratos 1, 2 y 3 en el servicio público domiciliario de acueducto, alcantarillado y aseo.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2344','4003029','Servicios de gestión para la instrumentación técnica y normativa en agua potable y saneamiento básico','Operaciones, acciones y/o trámites realizados para formular, estructurar y desarrollar los instrumentos técnicos y normativos que requiere el sector de Agua Potable y Saneamiento Básico para lograr los cometidos institucionales . ','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2345','4003004','Servicio de educación informal en regulación de Agua Potable y Saneamiento Básico',null,'184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2346','4003045','Unidades sanitarias con saneamiento básico mantenidas',null,'184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2347','4003024','Servicios de divulgación para el manejo de residuos solidos',null,'184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2348','4003042','Estudios de pre inversión e inversión','Incluye la realización de estudios de pre factibilidad, factibilidad o definitivos para la ejecución de proyectos','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2349','4003028','Servicios de educación informal en agua potable y saneamiento básico','Servicio a través del cual se hace la publicación y realización de eventos de difusión, divulgación o socialización de las políticas, planes, programas y proyectos del Viceministerio, a través de capacitaciones, talleres, mesas de trabajo, elaboración de guías, manual, entre otros.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2350','4003012','Soluciones de disposición final de residuos solidos construidas','Sitios dispuestos para disponer los residuos solidos recolectados en una zona','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2351','4003008','Servicio de apoyo financiero a los planes, programas y proyectos de Agua Potable y Saneamiento Básico','Financiación o Cofinanciación a planes, programas y proyectos relacionados con Agua Potable y Saneamiento Básico','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2352','4003041','Servicio de regulación en Agua Potable y Saneamiento Básico','Es el conjunto de actividades que permiten la expedición de la regulación de carácter general y particular en agua potable y saneamiento básico, basado en el conocimiento jurídico y técnico de la entidad.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2353','4003038','Servicio de asistencia técnica para la estructuración, formulación yejecución de planes y proyectos de agua potable y saneamiento básico','Conjunto de acciones encaminadas a la ejecución de los recursos asignados al Plan Departamental de Agua del Departamento de la Guajira, mediante la estructuración, formulación y ejecución de los planes y proyectos contenidos en el misma','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2354','4003022','Servicios de implementación del Plan de Gestión Integral de Residuos Solidos PGIRS','Contempla acciones realizadas para implementar el Plan de Gestión Integral de Residuos Solidos ','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2355','4003032','Servicio de apoyo técnico para el tratamiento de aguas residuales','Gestiones necesarias que se realizan para la obtención y análisis de información que requieren los Entes Territoriales en la implementación de sistemas de descontaminación de aguas.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2356','4003016','Acueductos ampliados','Conjunto de acciones y obras requeridas para aumentar la capacidad del acueducto en una misma área de cobertura.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2357','4003006','Documentos de planeación','Documentos cuyo objetivo es plasmar una visión de futuro a nivel país, entidad territorial, comunidad, sector, región, entidad o cualquier nivel de desagregación que se requiera. Incluye objetivos, estrategias, metas e indicadores','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2358','4003031','Estación de clasificación y aprovechamiento de residuos sólidos construida',null,'184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2359','4003043','Servicio de Asistencia técnica para la formulación, implementación y seguimiento de planes, programas y proyectos de agua potable y saneamiento básico','Se refiere al acompañamiento que el Ministerio realiza a las entidades territoriales y prestadoras de los servicios que lo soliciten en el tema de agua y saneamiento básico.','184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2360','4003044','Unidades sanitarias con saneamiento básico construidas',null,'184');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2616','4301028','Cancha mantenida','Obras para mantener el inmueble en las debidas condiciones de higiene y ornato sin afectar su materia original, su estructura portante, su distribución interior y sus características funcionales Incluye obras de mantenimiento y reparación como limpieza, renovación de pintura, eliminación de goteras, remplazo de piezas en mal estado, obras de drenaje, control de humedades.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2617','4301025','Cancha construida','Construcción de canchas, entendidas como el lugar específico donde se realiza una práctica deportiva, que puede ser cubierto o descubierto de acuerdo con la disciplina deportiva','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2618','4301029','Cancha mejorada','Obras que están destinadas a corregir las instalaciones existentes, a fin de garantizar mejores condiciones en la habitabilidad del espacio y la mejora consecuente en la prestación del servicio. Aumento de la cantidad de baterías sanitarias, la implementación de espacios de servicios que antes no se tenían.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2619','4301018','Canchas multifuncionales mejoradas','Obras que están destinadas a corregir las instalaciones existentes, a fin de garantizar mejores condiciones en la habitabilidad del espacio y la mejora consecuente en la prestación del servicio. Aumento de la cantidad de baterías sanitarias, la implementación de espacios de servicios que antes no se tenían.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2620','4301017','Canchas multifuncionales mantenidas','Obras para mantener el inmueble en las debidas condiciones de higiene y ornato sin afectar su materia original, su estructura portante, su distribución interior y sus características funcionales Incluye obras de mantenimiento y reparación como limpieza, renovación de pintura, eliminación de goteras, remplazo de piezas en mal estado, obras de drenaje, control de humedades.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2621','4301015','Canchas multifuncionales construidas y dotadas','Construcción y dotación de canchas multiformes para garantizar  la práctica de la actividad física, la recreación y el deporte.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2622','4301014','Canchas multifuncionales construidas.','Construcción de un escenario destinado para la práctica de baloncesto, voleibol y microfútbol, al cual se le ha construido una cubierta con el fin de optimizar su tiempo de uso. No tiene cerramientos laterales y habitualmente carece de graderías.  Las instalaciones cuentan con escenarios o tarimas de carácter fijo o móvil adecuadas para realizar actividades recreativas, cívicas o  culturales.   ','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2623','4301011','Parques recreativos adecuados','Obras necesarias para adaptar un inmueble o sus espacios o instalaciones a un nuevo uso, garantizando la preservación de sus características. Permiten modernizar las instalaciones, y optimizar y mejorar el uso de los espacios.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2624','4301007','Servicio de Escuelas Deportivas','Corresponde a los procesos de iniciación, fundamentación y perfeccionamiento deportivos a partir de  las clases donde se practica la actividad física, la recreación y/o el deporte.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2625','4301002','Servicio de apoyo financiero para la profesionalización de deportistas','Dentro del marco del Programa Supérate se entregan diferentes incentivos a los deportistas, docentes, entrenadores, establecimientos educativos, Juntas de Acción Comunal o resguardos que se hayan inscrito en las competencias del programa. El mayor estímulo otorgado a los ganadores en este programa es la entrega de créditos condonables del ICETEX  para el estudio de deportistas. ','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2626','4301003','Servicio de administración de la infraestructura deportiva','Corresponde al acceso y uso de la infraestructura deportiva para garantizar su operación por parte de las Entidades Territoriales. Implica la sostenibilidad del escenario entregado (servicios públicos, seguridad de los escenarios, garantías de la funcionalidad de la implementación deportiva necesaria para la práctica de la actividad física y  vías de acceso).','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2627','4301032','Servicio de organización de eventos deportivos comunitarios','Corresponde a la planeación, organización y realización de eventos deportivos en las diferentes disciplinas con la comunidad.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2628','4301024','Gimnasios al aire libre estáticos','Se realizan en el marco de la construcción de la modalidad de parques donde se habilita un sector para implementación de parques biosaludables  (mobiliario  para la practica de  ejercicios son estáticos)','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2629','4301021','Placa deportiva adecuada','Obras necesarias para adaptar un inmueble o sus espacios o instalaciones a un nuevo uso, garantizando la preservación de sus características. Permiten modernizar las instalaciones, y optimizar y mejorar el uso de los espacios.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2630','4301019','Placa deportiva construida','Construcción de  una placa polideportiva terminada en concreto, asfalto  o sintético, abierta por todos sus costados pero cubierta en teja generalmente metálica, soportada en pórticos habitualmente de estructura metálica con o sin iluminación y graderías, sin otros servicios conexos. Para realizar baloncesto, microfutbol, boleybol.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2631','4301010','Parques recreativos construidos y dotados','Construcción y dotación de infraestructura parques recreativos para garantizar  la práctica de la actividad física, la recreación y el deporte.','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2632','4301026','Cancha construida y dotada','Construcción y dotación de canchas, entendidas como el lugar específico donde se realiza una práctica deportiva, que puede ser cubierto o descubierto de acuerdo con la disciplina deportiva','192');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2633','4302069','Polideportivos mejorados','Obras que están destinadas a corregir las instalaciones existentes, a fin de garantizar mejores condiciones en la habitabilidad del espacio y la mejora consecuente en la prestación del servicio. Aumento de la cantidad de baterías sanitarias, la implementación de espacios de servicios que antes no se tenían.','193');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2634','4302908','Dotación implementación deportiva a las disciplinas deportivas','Producto Proyecto Regalías MGA Escritorio','193');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2635','4302907','Dotación equipos y materiales del centro biomédico','Producto Proyecto Regalías MGA Escritorio','193');
