Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2041','3699061','Servicios de información actualizados','Corresponde al proceso que mejora en la disposición de la información para asegurar que sea accesible, confiable y oportuna.','167');
