Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2361','4003010','Servicio de Aseo','Es el servicio de recolección municipal de residuos, principalmente sólidos. También se aplicará este servicio a las actividades complementarias de transporte, tratamiento, aprovechamiento y disposición final de tales residuos.','184');
