Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2390','4101019','Centros regionales de atención a víctimas ampliados','Ampliación de infraestructura en la cual se reúne la oferta institucional del nivel nacional y territorial que tiene como objetivo atender, orientar, remitir y acompañar a las víctimas del conflicto.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2391','4101009','Documentos de investigación','Contienen información sobre el conflicto armado interno y experiencias históricas de reconciliación en Colombia.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2392','4101006','Museos de Memoria Histórica con reforzamiento estructural','Infraestructura con reforzamiento estructural y habilitada al público para la divulgación del patrimonio documental y los archivos referidos a las  violaciones de Derechos Humanos e infracciones al Derecho Internacional Humanitario ocurridas con ocasión del conflicto armado interno de las que trata la Ley 1448 de 211.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2393','4101004','Museos de Memoria Histórica modificados','Infraestructura modificada y habilitada al público para la divulgación del patrimonio documental y los archivos referidos a las  violaciones de Derechos Humanos e infracciones al Derecho Internacional Humanitario ocurridas con ocasión del conflicto armado interno de las que trata la Ley 1448 de 211.','186');
