Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2395','4101070','Servicios de museología','Corresponde a la realización de las curadurías en el Museo Nacional de la Memoria. Incluye el desarrollo de guiones museográficos y la sistematización de las colecciones de interés.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2396','4101069','Servicio de asistencia técnica para el desarrollo de acciones pedagógicas en memoria histórica','Asistencia técnica que se  realiza a las instituciones y organizaciones en temas de pedagogía de memoria histórica.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2397','4101068','Servicios de divulgación de tematicas de memoria histórica','Comprende las  acciones de socialización de memoria histórica  por medio audiovisual, pedagógico, periodístico, artístico e investigativo ','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2398','4101071','Servicios de programación artística, cultural y académica del Museo Nacional de la Memoria','Mediante los cuales se realizan los eventos artísticos, culturales y académicos del Museo Nacional de la Memoria.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2399','4101081','Servicio de apoyo al fortalecimiento comunitario a los hogares en riesgo de desplazamiento, retornados o reubicados','Corresponde a la entrega de recursos en especie  dirigidos a la implementación de iniciativas de reconstrucción del tejido social y la integración comunitaria de los hogares en riesgo de desplazamiento, retornados, o reubicados.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2400','4101080','Servicio de asistencia técnica para la generación de ingresos','Corresponde a la formación y acompañamiento a los hogares desplazados o en riesgo de desplazamiento, en temas que fortalezcan sus capacidades empresariales, organizacionales y productivas para la generación de ingresos.','186');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2401','4101062','Centros comunitarios dotados','Dotación de infraestructura dispuesta a la comunidad para que pueda desarrollar actividades culturales, sociales y de formación. Hace parte de la Infraestructura Social que contribuye a los procesos de retorno y reubicación.','186');
