Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1739','3302070','Serviciode divulgación y publicación del Patrimonio cultural','Hace referencia a las actividades de divulgación a través de la página web de los museos, boletines informativos, redes sociales, etc. de los principales eventos académicos y culturales, exposiciones y programas. También referencia a las cartillas, libros, producción audiovisual, entre otras publicaciones elaboradas en temas de salvaguardia, protección, recuperación, conservación, sostenimiento y divulgación del Patrimonio Cultural de la Nación. Así como eventos como conferencias, conmemoraciones, conversatorios, encuentros, simposios etc. de carácter académico que permiten el fortalecimiento de la gestión universitaria y la consolidación de la comunidad docente e investigativa del Instituto. ','156');
