Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2067','3701005','Servicio de asistencia técnica en Derechos Humanos','La Dirección de Derechos Humanos del Ministerio del Interior, brindará asistencia técnica a las entidades territoriales para que a partir del diagnóstico participativo puedan identificar los problemas que en materia de vulneraciones a los derechos humanos, a la vida, la integridad, la libertad y la seguridad personal enfrenta la entidad territorial en particular.','168');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2068','3701004','Documentos de planeación','Documentos cuyo objetivo es plasmar una visión de futuro a nivel país, entidad territorial, comunidad, sector, región, entidad o cualquier nivel de desagregación que se requiera. Incluye objetivos, estrategias, metas e indicadores','168');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2069','3701012','Mapas de cementerios para la identificación de víctimas','Mapas cartográficos por cementerios  para la identificación de victimas y desaparición en el marco de las obligaciones del estado a nivel nacional realizados.','168');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2070','3701009','Servicio de información en Derechos Humanos, Derecho Internacional Humanitario y organizaciones étnicas.','Información dispersa que demanda ser recopilada y organizada para ser consultada.','168');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2071','3701003','Documentos metodológicos','Documentos cuyo objetivo es describir y explicar métodos, herramientas analíticas o procesos que determinan un camino o forma de realizar un análisis en particular. Específicamente contienen el protocolo de investigación, gestión documental y archivística en materia de violaciones de Derechos Humanos e Infracciones al Derecho Internacional Humanitario ocurridas con ocasión del conflicto armado interno colombiano.','168');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2072','3701002','Documentos de lineamientos técnicos','Documentos cuyo objetivo es describir y explicar instrumentos, estándares, requisitos y condiciones necesarias para llevar a cabo un proceso o actividad','168');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2073','3701015','Servicios de asistencia técnica territorial para la implementación de medidas afirmativas y ajustes razonables orientadas a personas con discapacidad.',null,'168');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('2074','3701023','Servicio de divulgación','Son acciones que se realizan para divulgar información de competencia del Ministerio del Interior.','168');
