Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1768','3399064','Servicios tecnológicos','Corresponde al proceso que asegura la disponibilidad del servicio a través de la infraestructura informática tanto de software como de hardware, y lo relacionado con seguridad informática.','157');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1769','3399016','Sedes mantenidas','Incluye mantenimiento preventivo y correctivo de edificios y zonas comunes,  trabajos de carpintería metálica y en maderareparaciones menores, trabajos de vidrios, trabajos de mampostería, trabajos de ornamentación, trabajos hidráulicos y sanitarios, servicios de jardinería, cortinería y cerrajería, pintura y reparación de muebles y pintura de espacios físicos.','157');
