Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1781','3501004','Servicio de apoyo para facilitar el comercio exterior a través de la Ventanilla Única de Comercio Exterior - VUCE','La Ventanilla Única de Comercio Exterior – VUCE- es un instrumento informático que permite el trámite electrónico de las autorizaciones, permisos, certificaciones o vistos buenos previos exigidos por las respectivas entidades del Estado para la realización de las operaciones específicas de importaciones y exportaciones.','158');
Insert into PRODUCT_CATALOG (ID,CODE,NAME,DESCRIPTION,PARENT_ID) values ('1782','3501003','Servicio de apoyo para la suscripción e implementación de acuerdos comerciales y de inversión','Se orienta al aprovechamiento de acuerdos comerciales, divulgación de oportunidades y diversificación de mercados, para fortalecer el tejido empresarial exportador y el crecimiento de la oferta exportable, facilitando la inserción en cadenas globales de valor y encadenamientos productivos regionales.','158');
